if( depth == CV_32F )
    minval = (int*)&fminval, maxval = (int*)&fmaxval;  // pointer aliased but correct memory
...
func( ptrs[0], ptrs[1], minval, maxval, &minidx, &maxidx, planeSize, startidx );
