Detailed description
Line: https://github.com/opencv/opencv/blob/4.13.0/modules/core/src/arithm.simd.hpp#L1437
template<typename T1, typename Tvec>
struct op_mul
{
    static inline Tvec r(const Tvec& a, const Tvec& b)
    { return v_mul(a, b); }
    static inline T1 r(T1 a, T1 b)
    { return saturate_cast<T1>(a * b); }
};

static inline T1 r(T1 a, T1 b) multiplication us done in the original T1 type. In case of T1 overflow saturation does not happen.
